sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_mode;
uniform float amzp_planes;
uniform float amzp_extent;
layout(color) uniform half4 amzp_lineCol;
layout(color) uniform half4 amzp_bgCol;
layout(color) uniform half4 amzp_floorCol;
layout(color) uniform half4 amzp_checkCol;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float amzp_alpha;
uniform float amzp_gridSize;
uniform float amzp_floorY;
uniform float amzp_subDiv;
uniform float amzp_subOp;
uniform float amzp_spokes;
uniform float amzp_space;
uniform float2 amzp_boardArea;
uniform float amzp_edgeFeather;
uniform float amzp_lineW;
uniform float amzp_glow;
uniform float amzp_fadeDist;
uniform float amzp_planeShade;
uniform float amzp_horOn;
layout(color) uniform half4 amzp_horCol;
uniform float amzp_horGlow;
uniform float amzp_camMode;
uniform float amzp_camTilt;
uniform float amzp_camPan;
uniform float amzp_camZoom;
uniform float amzp_camDolly;
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_overdrawOn;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_ufOn;
layout(color) uniform half4 amzp_ufCol;
uniform float amzp_ufLines;
layout(color) uniform half4 amzp_ufLineCol;
    uniform float4x4 nmModel;
    uniform float4x4 nmView;
    uniform float4x4 nmProj;
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        return f + b * (1.0 - f.a);
    }
    float2 pScl(float2 u) { return u / (max(amzp_scale * 2.0, 0.002) * max(amzp_stretch, float2(0.01))); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    bool SCN;
    float3 CP;
    float3 RO;
    float3 MO;
    float3x3 MI;
    float CA, SA;
    float camOK() { return (nmProj[2][3] > 0.5 && abs(nmProj[0][0]) + abs(nmProj[1][1]) > 1e-6) ? 1.0 : 0.0; }
    float3 rayDir(float2 q) {
        if (SCN) {
            float3 r0 = float3(nmProj[0][0], nmProj[1][0], nmProj[2][0]);
            float3 r1 = float3(nmProj[0][1], nmProj[1][1], nmProj[2][1]);
            float3 rw = float3(nmProj[0][3], nmProj[1][3], nmProj[2][3]);
            float3 d = cross(r0 - q.x * rw, r1 - q.y * rw);
            if (d.z < 0.0) d = -d;
            float3 c0 = nmView[0].xyz, c1 = nmView[1].xyz, c2 = nmView[2].xyz;
            float3 w = float3(dot(c0, d) / max(dot(c0, c0), 1e-8), dot(c1, d) / max(dot(c1, c1), 1e-8), dot(c2, d) / max(dot(c2, c2), 1e-8));
            return normalize(w);
        }
        float3 d = normalize(float3(q, max(amzp_camZoom, 1.0)));
        float t = radians(amzp_camTilt), p = radians(amzp_camPan);
        d = float3(d.x, d.y * cos(t) + d.z * sin(t), -d.y * sin(t) + d.z * cos(t));
        d = float3(d.x * cos(p) + d.z * sin(p), d.y, -d.x * sin(p) + d.z * cos(p));
        return d;
    }
    float3 camPos() {
        if (SCN) {
            float3 c0 = nmView[0].xyz, c1 = nmView[1].xyz, c2 = nmView[2].xyz;
            float3 t = nmView[3].xyz;
            return -float3(dot(c0, t) / max(dot(c0, c0), 1e-8), dot(c1, t) / max(dot(c1, c1), 1e-8), dot(c2, t) / max(dot(c2, c2), 1e-8));
        }
        return float3(0.0, 0.0, -max(amzp_camZoom, 1.0) + amzp_camDolly);
    }
    void setupModel() {
        float3 X = float3(1.0, 0.0, 0.0), Y = float3(0.0, 1.0, 0.0), Z = float3(0.0, 0.0, 1.0);
        MO = float3(0.0);
        if (int(amzp_space) == 0) {
            float3 mx = nmModel[0].xyz, my = nmModel[1].xyz, mz = nmModel[2].xyz;
            float lx = length(mx), ly = length(my), lz = length(mz);
            float det = dot(mx, cross(my, mz));
            if (lx > 1e-6 && ly > 1e-6 && lz > 1e-6 && abs(det) > 1e-9 && abs(nmModel[3][3] - 1.0) < 0.01) {
                X = mx; Y = my; Z = mz / lz * 0.5 * (lx + ly);
                MO = nmModel[3].xyz;
            }
        }
        float3 a = cross(Y, Z), b = cross(Z, X), c = cross(X, Y);
        float dt = dot(X, a);
        dt = abs(dt) < 1e-12 ? 1e-12 : dt;
        MI = float3x3(float3(a.x, b.x, c.x), float3(a.y, b.y, c.y), float3(a.z, b.z, c.z)) / dt;
    }
    float3 toRoomDir(float3 d) {
        float3 l = MI * d;
        return float3(CA * l.x - SA * l.z, l.y, SA * l.x + CA * l.z);
    }
    float3 toRoomPos(float3 p) {
        float3 l = MI * (p - MO) - float3(amzp_position.x, 0.0, amzp_position.y);
        return float3(CA * l.x - SA * l.z, l.y, SA * l.x + CA * l.z);
    }
    bool planeOn(int i) {
        if (int(amzp_planes) == 0) return i == 0;
        if (int(amzp_planes) == 1) return i == 1;
        if (int(amzp_planes) == 2) return i < 2;
        if (int(amzp_planes) == 3) return i < 4;
        return true;
    }
    float2 boardPx() {
        if (int(amzp_extent) != 1) return float2(0.0);
        return max(floor(amzp_boardArea + 0.5), float2(1.0)) * max(amzp_gridSize, 1.0);
    }
    float roomHW() {
        return int(amzp_extent) == 1 ? 0.5 * boardPx().x : 6.0 * max(amzp_gridSize, 1.0);
    }
    float roomHD() {
        return int(amzp_extent) == 1 ? 0.5 * boardPx().y : 6.0 * max(amzp_gridSize, 1.0);
    }
    float hitRaw(float3 rd, int i) {
        float fy = amzp_floorY;
        float hw = roomHW();
        float den, num;
        if (i == 0) { den = rd.y; num = fy - RO.y; }
        else if (i == 1) { den = rd.y; num = -fy - RO.y; }
        else if (i == 2) { den = rd.x; num = hw - RO.x; }
        else if (i == 3) { den = rd.x; num = -hw - RO.x; }
        else if (i == 4) { den = rd.z; num = roomHD() - RO.z; }
        else { den = rd.z; num = -roomHD() - RO.z; }
        if (abs(den) < 1e-9) return -1.0;
        return num / den;
    }
    float2 planeUV(float3 h, int i) {
        if (i < 2) return float2(h.x, h.z);
        if (i < 4) return float2(h.y, h.z);
        return float2(h.x, h.y);
    }
    float planeEdge(float3 h, int i) {
        float e = -1e9;
        float fy = abs(amzp_floorY);
        float hw = roomHW();
        float2 floorSize = boardPx();
        if (int(amzp_planes) == 4) { if (i < 4) e = max(e, abs(h.z) - roomHD()); }
        else if (floorSize.y > 0.0) e = max(e, abs(h.z) - 0.5 * floorSize.y);
        if (i < 2) {
            if (floorSize.x > 0.0) e = max(e, abs(h.x) - 0.5 * floorSize.x);
            if (int(amzp_planes) >= 3) e = max(e, abs(h.x) - hw);
        } else if (i < 4) {
            e = max(e, abs(h.y) - fy);
        } else {
            e = max(e, max(abs(h.x) - hw, abs(h.y) - fy));
        }
        return e;
    }
    float featEdge(float3 h, int i) {
        float e = -1e9;
        float2 fs = boardPx();
        if (fs.y > 0.0 && int(amzp_planes) != 4) e = max(e, abs(h.z) - 0.5 * fs.y);
        if (i < 2 && int(amzp_planes) < 3 && fs.x > 0.0) e = max(e, abs(h.x) - 0.5 * fs.x);
        return e;
    }
    float lineCov(float c, float s, float fw, float hw) {
        float d = abs(fract(c / s + 0.5) - 0.5) * s;
        float cov = 1.0 - smoothstep(hw - fw * 0.5, hw + fw * 0.5, d);
        float avg = clamp(2.0 * hw / s, 0.0, 1.0);
        return mix(cov, avg, smoothstep(0.2, 0.6, fw / s));
    }
    float glowCov(float c, float s, float fw, float hw) {
        float d = abs(fract(c / s + 0.5) - 0.5) * s;
        float g = exp(-d / max(hw * 4.0 + fw, 1e-3));
        return mix(g, 0.0, smoothstep(0.15, 0.5, fw / s));
    }
    void amzRender() {
        float4 orig = amzTexture(0, amzScreenNorm());
        float gPsc = screen.zw.y / max(screen.zw.y, 1.0);
        float2 pix = float2(amzScreenNorm().x, 1.0 - amzScreenNorm().y) * screen.zw;
        float2 q = (pix - screen.zw * 0.5) / gPsc;
        SCN = int(amzp_camMode) == 0 && camOK() > 0.5;
        CP = camPos();
        float ga = radians(amzp_angle);
        CA = cos(ga); SA = sin(ga);
        setupModel();
        RO = toRoomPos(CP);
        float3 dW = rayDir(q);
        float3 rd = toRoomDir(dW);
        float3 rdx = toRoomDir(rayDir(q + float2(1.0 / gPsc, 0.0)));
        float3 rdy = toRoomDir(rayDir(q + float2(0.0, 1.0 / gPsc)));
        float tb = 1e20;
        int pi = -1;
        for (int i = 0; i < 6; i++) {
            if (!planeOn(i)) continue;
            float t = hitRaw(rd, i);
            if (t <= 0.0) continue;
            float3 h = RO + rd * t;
            float mg = (int(amzp_extent) == 1 && int(amzp_mode) != 1) ? 0.5 * amzp_lineW * length(rdx - rd) * t : 0.0;
            if (planeEdge(h, i) > mg) continue;
            if (t < tb) { tb = t; pi = i; }
        }
        float4 G = float4(0.0);
        if (pi >= 0) {
            float3 h0 = RO + rd * tb;
            float2 uv0 = pScl(planeUV(h0, pi));
            float tx = hitRaw(rdx, pi), ty = hitRaw(rdy, pi);
            float fw = (tx > 0.0 && ty > 0.0) ? max(length(pScl(planeUV(RO + rdx * tx, pi)) - uv0), length(pScl(planeUV(RO + rdy * ty, pi)) - uv0)) : 1e6;
            float2 e0 = planeUV(h0, pi);
            float fwR = (tx > 0.0 && ty > 0.0) ? max(length(planeUV(RO + rdx * tx, pi) - e0), length(planeUV(RO + rdy * ty, pi) - e0)) : 1e6;
            float2 fwA = float2(fw);
            float fwE = fwR;
            float edge = planeEdge(h0, pi);
            if (tx > 0.0 && ty > 0.0) {
                float2 uX = pScl(planeUV(RO + rdx * tx, pi)) - uv0, uY = pScl(planeUV(RO + rdy * ty, pi)) - uv0;
                fwA = float2(length(float2(uX.x, uY.x)), length(float2(uX.y, uY.y)));
                if (edge > -1e8) fwE = length(float2(planeEdge(RO + rdx * tx, pi) - edge, planeEdge(RO + rdy * ty, pi) - edge));
            }
            fwE = max(fwE, 1e-4);
            float2 f = uv0;
            if (int(amzp_extent) == 1) {
                float2 oddT = 0.5 * max(amzp_gridSize, 1.0) * mod(max(floor(amzp_boardArea + 0.5), float2(1.0)), 2.0);
                f += float2((pi < 2 || pi >= 4) ? oddT.x : 0.0, pi < 4 ? oddT.y : 0.0);
            }
            if (pi < 4) f.y += TT() * amzp_gridSize;
            float hw = 0.5 * amzp_lineW * fw;
            float s = max(amzp_gridSize, 1.0);
            float sub = max(floor(amzp_subDiv + 0.5), 1.0);
            float lc = 0.0, amzSource_gl = 0.0;
            if (int(amzp_mode) == 0 || int(amzp_mode) == 3) {
                float hwX = 0.5 * amzp_lineW * fwA.x, hwY = 0.5 * amzp_lineW * fwA.y;
                lc = lineCov(f.x, s, fwA.x, hwX);
                amzSource_gl = glowCov(f.x, s, fwA.x, hwX);
                if (int(amzp_mode) == 0) { lc = max(lc, lineCov(f.y, s, fwA.y, hwY)); amzSource_gl = max(amzSource_gl, glowCov(f.y, s, fwA.y, hwY)); }
                if (sub > 1.0) {
                    float ls = lineCov(f.x, s / sub, fwA.x, hwX * 0.7);
                    if (int(amzp_mode) == 0) ls = max(ls, lineCov(f.y, s / sub, fwA.y, hwY * 0.7));
                    lc = max(lc, ls * amzp_subOp);
                }
            } else if (int(amzp_mode) == 1) {
                float2 c = (fract(f / s + 0.5) - 0.5) * s;
                float r = max(hw * 2.0, 0.5);
                lc = 1.0 - smoothstep(r - fw * 0.5, r + fw * 0.5, length(c));
                lc = mix(lc, clamp(3.14159265 * r * r / (s * s), 0.0, 1.0), smoothstep(0.2, 0.6, fw / s));
                amzSource_gl = exp(-length(c) / max(r * 3.0 + fw, 1e-3)) * (1.0 - smoothstep(0.15, 0.5, fw / s));
            } else {
                float2 fc = uv0;
                float rr = length(fc);
                float an = atan(fc.y, fc.x);
                lc = lineCov(rr - TT() * amzp_gridSize, s, fw, hw);
                amzSource_gl = glowCov(rr - TT() * amzp_gridSize, s, fw, hw);
                float sp = max(floor(amzp_spokes + 0.5), 1.0);
                float arc = abs(fract(an / 6.28318531 * sp + 0.5) - 0.5) * 6.28318531 / sp * rr;
                float sc = 1.0 - smoothstep(hw - fw * 0.5, hw + fw * 0.5, arc);
                sc *= smoothstep(0.0, s * 0.5, rr);
                lc = max(lc, sc * (1.0 - smoothstep(0.2, 0.6, fw * sp / max(rr * 6.28318531, 1.0))));
            }
            float featPx = amzp_edgeFeather * max(amzp_gridSize, 1.0) * max(amzp_scale * 2.0, 0.002);
            float fedge = featEdge(h0, pi);
            float fe = (fedge < -1e8 || featPx <= 1e-4) ? 1.0 : smoothstep(0.0, featPx, -fedge);
            lc *= fe; amzSource_gl *= fe;
            if (int(amzp_extent) == 1 && int(amzp_mode) != 1) {
                float hwR = 0.5 * amzp_lineW * fwE;
                lc = max(lc, 1.0 - smoothstep(hwR - fwE * 0.5, hwR + fwE * 0.5, abs(edge)));
                amzSource_gl = max(amzSource_gl, exp(-abs(edge) / max(hwR * 4.0 + fwE, 1e-3)));
            }
            float mg0 = (int(amzp_extent) == 1 && int(amzp_mode) != 1) ? 0.5 * amzp_lineW * fwE : 0.0;
            float ea = 1.0 - smoothstep(mg0 - fwE, mg0, edge);
            if (edge < -1e8) ea = 1.0;
            float fdPx = 200.0 * pow(5000.0, clamp(amzp_fadeDist, 0.0, 1.0));
            float fade = (amzp_fadeDist >= 0.995 ? 1.0 : exp(-tb / fdPx)) * ea;
            float shade = pi == 0 ? 1.0 : 1.0 - clamp(amzp_planeShade, 0.0, 1.0);
            float fa = amzp_floorCol.a * fade;
            G = float4(amzp_floorCol.rgb * shade * fa, fa);
            if (amzp_checkCol.a > 0.0 && int(amzp_mode) != 2) {
                float2 ci = floor(f / s);
                float par = mod(ci.x + (int(amzp_mode) == 3 ? 0.0 : ci.y), 2.0);
                float cm = mix(step(0.5, par), 0.5, smoothstep(0.2, 0.6, fw / s));
                float ck = amzp_checkCol.a * cm * fade;
                G = float4(amzp_checkCol.rgb * shade * ck, ck) + G * (1.0 - ck);
            }
            float la = clamp(lc * fade * amzp_lineCol.a, 0.0, 1.0);
            G = float4(amzp_lineCol.rgb * shade * la, la) + G * (1.0 - la);
            float ga = clamp(amzSource_gl * amzp_glow * fade * 0.6 * amzp_lineCol.a, 0.0, 1.0);
            G.rgb += amzp_lineCol.rgb * shade * ga * (1.0 - G.a);
            G.a = G.a + ga * (1.0 - G.a);
        }
        if ((amzp_horOn>0.5) && amzp_horGlow > 0.0 && int(amzp_planes) < 3) {
            float3 rn = normalize(rd);
            float e = abs(asin(clamp(rn.y, -1.0, 1.0)));
            float ha = clamp(amzp_horGlow * exp(-e * 10.0), 0.0, 1.0) * (1.0 - G.a * 0.5);
            G.rgb += amzp_horCol.rgb * ha;
            G.a = G.a + ha * (1.0 - G.a);
        }
        G += float4(amzp_bgCol.rgb * amzp_bgCol.a, amzp_bgCol.a) * (1.0 - G.a);
        G = clamp(G, 0.0, 1.0);
        G.rgb = min(G.rgb, float3(G.a));
        amzOutput = nmBlend(orig, G);
        if (!(amzp_overdrawOn>0.5)) amzOutput *= orig.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
